/// <summary>
/// Returns a human-readable string representation using the largest whole number unit.
/// </summary>
public override string ToString() => ToString("0.##", CultureInfo.CurrentCulture);

/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    if (TryFormatUnit(format, formatProvider, TerabyteSymbol, Terabytes, out var result)) return result;
    if (TryFormatUnit(format, formatProvider, GigabyteSymbol, Gigabytes, out result)) return result;
    if (TryFormatUnit(format, formatProvider, MegabyteSymbol, Megabytes, out result)) return result;
    if (TryFormatUnit(format, formatProvider, KilobyteSymbol, Kilobytes, out result)) return result;
    if (TryFormatUnit(format, formatProvider, ByteSymbol, Bytes, out result)) return result;
    if (TryFormatUnit(format, formatProvider, BitSymbol, Bits, out result)) return result;

    var (value, symbol) = LargestWholeNumber;
    return string.Concat(value.ToString(format, formatProvider), " ", symbol);
}

private static bool TryFormatUnit(
    string format, IFormatProvider formatProvider,
    string symbol, double value, out string result)
{
    int idx = format.IndexOf(symbol, StringComparison.OrdinalIgnoreCase);
    if (idx < 0)
    {
        result = "";
        return false;
    }

    // Extract numeric format (portion before the symbol)
    var numericFormat = format.AsSpan(0, idx).TrimEnd();
    result = string.Concat(value.ToString(numericFormat.ToString(), formatProvider), " ", symbol);
    return true;
}

